import * as THREE from 'three';

function hash(ix: number, iy: number, seed: number): number {
  let h = Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = h ^ (h >>> 16);
  return (h >>> 0) / 4294967295;
}

function vnoise(x: number, y: number, seed: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = x - ix;
  const fy = y - iy;
  const sx = fx * fx * (3 - 2 * fx);
  const sy = fy * fy * (3 - 2 * fy);
  const a = hash(ix, iy, seed);
  const b = hash(ix + 1, iy, seed);
  const c = hash(ix, iy + 1, seed);
  const d = hash(ix + 1, iy + 1, seed);
  return a + (b - a) * sx + (c - a) * sy + (a - b - c + d) * sx * sy;
}

function fbm(x: number, y: number, seed: number, oct: number): number {
  let sum = 0;
  let amp = 0.5;
  let f = 1;
  for (let i = 0; i < oct; i++) {
    sum += amp * vnoise(x * f, y * f, seed + i * 17);
    f *= 2.03;
    amp *= 0.5;
  }
  return sum;
}

function turbulence(x: number, y: number, seed: number, oct: number): number {
  let sum = 0;
  let amp = 0.5;
  let f = 1;
  for (let i = 0; i < oct; i++) {
    sum += amp * Math.abs(vnoise(x * f, y * f, seed + i * 31) - 0.5) * 2;
    f *= 2.1;
    amp *= 0.5;
  }
  return sum;
}

function smoothstep(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

/** Carrara-style white marble with grey veins from turbulence-warped stripes. */
export function makeMarbleTexture(seed: number, size = 768): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;
  const img = ctx.createImageData(size, size);
  const d = img.data;
  const ang = 0.5 + seed * 0.7;
  const ca = Math.cos(ang);
  const sa = Math.sin(ang);
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const u = px / size;
      const v = py / size;
      const x = u * 3.2;
      const y = v * 3.2;
      // cloudy tone variation
      const cloud = fbm(x * 1.3 + seed * 5, y * 1.3, seed, 5);
      // main veins
      const along = (u * ca + v * sa) * 2.4;
      const warp = turbulence(x * 0.9 + seed, y * 0.9, seed + 3, 6);
      const t1 = along + warp * 2.6;
      let v1 = Math.pow(1 - Math.abs(Math.sin(t1 * Math.PI)), 22);
      const mask1 = smoothstep(0.3, 0.62, fbm(x * 0.7 + 9, y * 0.7 + seed, seed + 8, 4));
      v1 *= 0.35 + 0.65 * mask1;
      // secondary finer veins, different direction
      const along2 = (u * sa - v * ca) * 5.0;
      const warp2 = turbulence(x * 1.7 + 4, y * 1.7 + seed * 2, seed + 11, 6);
      const t2 = along2 + warp2 * 3.4;
      let v2 = Math.pow(1 - Math.abs(Math.sin(t2 * Math.PI)), 40);
      const mask2 = smoothstep(0.4, 0.7, fbm(x * 1.1 + 20, y * 1.1, seed + 14, 4));
      v2 *= mask2 * 0.7;
      // soft haze around main veins
      const haze = Math.pow(1 - Math.abs(Math.sin(t1 * Math.PI)), 5) * 0.12 * mask1;
      const fine = (vnoise(px * 0.5, py * 0.5, seed + 40) - 0.5) * 0.015;

      const base = 0.93 - cloud * 0.07 + fine;
      const vein = Math.min(1, v1 * 0.85 + v2 * 0.5 + haze);
      const grey = 0.46 + 0.1 * fbm(x * 3, y * 3, seed + 50, 3);
      const k = vein;
      const r = base * (1 - k) + grey * k + 0.005;
      const g = base * (1 - k) + (grey + 0.005) * k;
      const b = base * (1 - k) + (grey + 0.03) * k - 0.005;
      const i = (py * size + px) * 4;
      d[i] = Math.min(255, Math.max(0, r * 255));
      d[i + 1] = Math.min(255, Math.max(0, g * 255 * 0.992));
      d[i + 2] = Math.min(255, Math.max(0, b * 255 * 0.98));
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

/** Dark warm floor with faint plank structure. */
export function makeFloorTexture(size = 512): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;
  const img = ctx.createImageData(size, size);
  const d = img.data;
  const planks = 8;
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const plank = Math.floor((px / size) * planks);
      const shade = 0.75 + 0.25 * hash(plank, 3, 5);
      const grain = fbm(px * 0.01 + plank * 7, py * 0.12, 21, 4);
      let val = shade * (0.7 + 0.5 * grain);
      const edge = (px / size) * planks - plank;
      if (edge < 0.02 || edge > 0.98) val *= 0.4;
      const i = (py * size + px) * 4;
      d[i] = Math.min(255, val * 70);
      d[i + 1] = Math.min(255, val * 50);
      d[i + 2] = Math.min(255, val * 36);
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 8;
  return tex;
}

/** Bump map for an engraved band: greek-key style zigzag (dark = recessed). */
export function makeEngravingBump(): THREE.CanvasTexture {
  const w = 1024;
  const h = 128;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 6;
  ctx.lineJoin = 'miter';
  const reps = 32;
  const step = w / reps;
  for (const [y0, y1] of [[34, 60], [68, 94]] as const) {
    ctx.beginPath();
    for (let i = 0; i <= reps; i++) {
      const x = i * step;
      ctx.lineTo(x, i % 2 === 0 ? y0 : y1);
    }
    ctx.stroke();
  }
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 14, w, 5);
  ctx.fillRect(0, h - 19, w, 5);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.anisotropy = 8;
  return tex;
}

/** Bump map for the name plate. */
export function makePlateBump(): THREE.CanvasTexture {
  const w = 512;
  const h = 128;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 4;
  ctx.strokeRect(10, 10, w - 20, h - 20);
  ctx.fillStyle = '#000';
  ctx.font = 'bold 54px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('CHAMPION', w / 2, h / 2 + 2);
  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

import * as THREE from 'three';

function emissive(r: number, g: number, b: number): THREE.MeshBasicMaterial {
  const m = new THREE.MeshBasicMaterial();
  m.color.setRGB(r, g, b);
  m.side = THREE.DoubleSide;
  return m;
}

/** A window with a 2-column mullion grid, facing the room centre. */
function addWindow(
  parent: THREE.Object3D,
  pos: THREE.Vector3,
  w: number,
  h: number,
  cols: number,
  rows: number,
  color: [number, number, number],
): void {
  const g = new THREE.Group();
  const gap = 0.12;
  const pw = (w - gap * (cols - 1)) / cols;
  const ph = (h - gap * (rows - 1)) / rows;
  const mat = emissive(...color);
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(pw, ph), mat);
      m.position.set(-w / 2 + pw / 2 + i * (pw + gap), -h / 2 + ph / 2 + j * (ph + gap), 0);
      g.add(m);
    }
  }
  g.position.copy(pos);
  g.lookAt(0, pos.y, 0);
  parent.add(g);
}

function addLamp(parent: THREE.Object3D, pos: THREE.Vector3, r: number, color: [number, number, number]): void {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 16, 12), emissive(...color));
  m.position.copy(pos);
  parent.add(m);
}

/** Procedural dark gallery with a few bright windows and lamps, prefiltered for PBR reflections. */
export function createEnvironment(renderer: THREE.WebGLRenderer): THREE.Texture {
  const s = new THREE.Scene();

  const room = new THREE.Mesh(
    new THREE.BoxGeometry(24, 14, 24),
    new THREE.MeshBasicMaterial({ color: 0x1a1009, side: THREE.BackSide }),
  );
  room.position.y = 6;
  s.add(room);

  // dim warm floor glow / darker floor
  const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(24, 24),
    new THREE.MeshBasicMaterial({ color: 0x0b0705, side: THREE.DoubleSide }),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.99;
  s.add(floor);

  // back wall windows (warm daylight)
  addWindow(s, new THREE.Vector3(-4.5, 4, -11.8), 2.6, 6, 2, 3, [7, 5.6, 3.8]);
  addWindow(s, new THREE.Vector3(4.5, 4, -11.8), 2.6, 6, 2, 3, [7, 5.6, 3.8]);
  // left wall: cool window
  addWindow(s, new THREE.Vector3(-11.8, 4, 1), 3.4, 5.5, 2, 3, [2.6, 3.6, 6.5]);
  // right wall: tall warm window
  addWindow(s, new THREE.Vector3(11.8, 3.5, -3), 2.2, 6, 1, 3, [8, 5.5, 3]);
  // front wall (behind camera): wide window and lamp
  addWindow(s, new THREE.Vector3(3, 4, 11.8), 4, 4.5, 3, 2, [6, 4.6, 3]);
  addWindow(s, new THREE.Vector3(-6, 3, 11.8), 1.6, 5, 1, 2, [3, 3.5, 5]);

  // ceiling strip lights
  for (const x of [-3, 3]) {
    const strip = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 14), emissive(9, 6.2, 3.4));
    strip.rotation.x = Math.PI / 2;
    strip.position.set(x, 12.9, 0);
    s.add(strip);
  }

  // lamps
  addLamp(s, new THREE.Vector3(-8, 2.5, 7), 0.5, [18, 11, 4.5]);
  addLamp(s, new THREE.Vector3(8.5, 3, 6), 0.45, [16, 10, 4]);
  addLamp(s, new THREE.Vector3(-7, 5, -6), 0.35, [14, 9, 4]);
  addLamp(s, new THREE.Vector3(7, 1.8, -8), 0.4, [12, 8, 3.5]);

  const pmrem = new THREE.PMREMGenerator(renderer);
  const rt = pmrem.fromScene(s, 0.015);
  pmrem.dispose();
  return rt.texture;
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import { createEnvironment } from './environment';
import { makeEngravingBump, makeFloorTexture, makeMarbleTexture, makePlateBump } from './textures';

declare global {
  interface Window {
    __TASK_STATE__: { materials: string[]; cameraAzimuthDeg: number };
    __EVAL_READY__?: boolean;
  }
}

const canvas = document.getElementById('app') as HTMLCanvasElement;
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(1);
renderer.setSize(640, 360, false);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0705);
scene.fog = new THREE.Fog(0x0a0705, 14, 30);

const envMap = createEnvironment(renderer);

const camera = new THREE.PerspectiveCamera(35, 640 / 360, 0.1, 80);
const target = new THREE.Vector3(0, 1.7, 0);

// ---------- Materials ----------
const marbleTexA = makeMarbleTexture(1);
const marbleTexB = makeMarbleTexture(2);

function marbleMaterial(map: THREE.Texture): THREE.MeshPhysicalMaterial {
  return new THREE.MeshPhysicalMaterial({
    map,
    roughness: 0.2,
    metalness: 0,
    clearcoat: 0.7,
    clearcoatRoughness: 0.06,
    envMap,
    envMapIntensity: 0.55,
  });
}
const marbleColumn = marbleMaterial(marbleTexA);
const marbleSteps = marbleMaterial(marbleTexB);

const gold = new THREE.MeshPhysicalMaterial({
  color: 0xffc65a,
  metalness: 1,
  roughness: 0.1,
  envMap,
  envMapIntensity: 1.6,
});
const goldEngraved = new THREE.MeshPhysicalMaterial({
  color: 0xb8892e,
  metalness: 1,
  roughness: 0.42,
  envMap,
  envMapIntensity: 1.2,
  bumpMap: makeEngravingBump(),
  bumpScale: 2.5,
});
const goldDarkPlain = new THREE.MeshPhysicalMaterial({
  color: 0xb8892e,
  metalness: 1,
  roughness: 0.4,
  envMap,
  envMapIntensity: 1.2,
});
const plateBump = makePlateBump();
const goldPlate = new THREE.MeshPhysicalMaterial({
  color: 0xffc65a,
  metalness: 1,
  roughness: 0.18,
  envMap,
  envMapIntensity: 1.5,
  bumpMap: plateBump,
  bumpScale: 1.5,
});
const darkstone = new THREE.MeshPhysicalMaterial({
  color: 0x0b0b0d,
  metalness: 0,
  roughness: 0.14,
  clearcoat: 1,
  clearcoatRoughness: 0.03,
  envMap,
  envMapIntensity: 0.9,
});

function shadowed<T extends THREE.Mesh>(m: T, cast = true, receive = true): T {
  m.castShadow = cast;
  m.receiveShadow = receive;
  return m;
}

// ---------- Room ----------
const floorTex = makeFloorTexture();
floorTex.repeat.set(5, 5);
const floor = shadowed(
  new THREE.Mesh(
    new THREE.PlaneGeometry(30, 30),
    new THREE.MeshStandardMaterial({
      map: floorTex,
      roughness: 0.38,
      metalness: 0,
      envMap,
      envMapIntensity: 0.25,
    }),
  ),
  false,
  true,
);
floor.rotation.x = -Math.PI / 2;
scene.add(floor);

const wall = shadowed(
  new THREE.Mesh(
    new THREE.PlaneGeometry(30, 14),
    new THREE.MeshStandardMaterial({ color: 0x4a3524, roughness: 0.85, metalness: 0 }),
  ),
  false,
  true,
);
wall.position.set(0, 7, -3.8);
scene.add(wall);

// ---------- Pedestal ----------
const pedestal = new THREE.Group();
scene.add(pedestal);

function slab(w: number, h: number, d: number, y: number, mat: THREE.Material, r: number): void {
  const m = shadowed(new THREE.Mesh(new RoundedBoxGeometry(w, h, d, 3, r), mat));
  m.position.y = y + h / 2;
  pedestal.add(m);
}
slab(1.95, 0.16, 1.95, 0.0, marbleSteps, 0.012);
slab(1.58, 0.16, 1.58, 0.16, marbleSteps, 0.012);
slab(1.15, 1.2, 1.15, 0.32, marbleColumn, 0.01);
slab(1.4, 0.12, 1.4, 1.52, marbleSteps, 0.015);
const PED_TOP = 1.64;

// ---------- Trophy base (black polished stone) + gold plate ----------
const baseH = 0.2;
const stoneBase = shadowed(new THREE.Mesh(new RoundedBoxGeometry(0.95, baseH, 0.95, 4, 0.02), darkstone));
stoneBase.position.y = PED_TOP + baseH / 2;
scene.add(stoneBase);
const plate = shadowed(new THREE.Mesh(new RoundedBoxGeometry(0.5, 0.12, 0.012, 2, 0.004), goldPlate), true, false);
plate.position.set(0, PED_TOP + baseH / 2, 0.475 + 0.004);
scene.add(plate);

// ---------- Trophy ----------
const trophy = new THREE.Group();
trophy.position.y = PED_TOP + baseH;
trophy.scale.setScalar(1.15);
scene.add(trophy);

function spline2(pts: [number, number][], n: number): THREE.Vector2[] {
  const curve = new THREE.SplineCurve(pts.map(([x, y]) => new THREE.Vector2(x, y)));
  return curve.getPoints(n).map((p) => new THREE.Vector2(Math.max(0, p.x), p.y));
}

const outer = spline2(
  [
    [0.3, 0.0],
    [0.3, 0.025],
    [0.26, 0.06],
    [0.14, 0.1],
    [0.07, 0.17],
    [0.055, 0.28],
    [0.1, 0.34],
    [0.118, 0.37],
    [0.1, 0.4],
    [0.055, 0.46],
    [0.05, 0.53],
    [0.09, 0.6],
    [0.2, 0.68],
    [0.32, 0.8],
    [0.395, 0.95],
    [0.415, 1.1],
    [0.41, 1.17],
  ],
  220,
);
const lip: THREE.Vector2[] = [
  new THREE.Vector2(0.412, 1.18),
  new THREE.Vector2(0.4, 1.195),
  new THREE.Vector2(0.386, 1.18),
];
const inner = spline2(
  [
    [0.385, 1.16],
    [0.37, 1.0],
    [0.3, 0.86],
    [0.15, 0.76],
    [0.0, 0.72],
  ],
  60,
);
const cupGeo = new THREE.LatheGeometry([...outer, ...lip, ...inner], 96);
trophy.add(shadowed(new THREE.Mesh(cupGeo, gold)));

// engraved band following the cup wall
const bandPts: THREE.Vector2[] = [];
const bandOuter = outer.filter((p) => p.y >= 0.76 && p.y <= 0.88);
bandOuter.forEach((p, i) => {
  const s = i / (bandOuter.length - 1);
  bandPts.push(new THREE.Vector2(p.x + 0.002 + 0.008 * Math.sin(Math.PI * s) ** 0.4, p.y));
});
trophy.add(shadowed(new THREE.Mesh(new THREE.LatheGeometry(bandPts, 96), goldEngraved), true, false));

// thin dark-gold ring on stem and at foot
function ring(y: number, radius: number, tube: number, mat: THREE.Material): void {
  const m = shadowed(new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 14, 64), mat), true, false);
  m.rotation.x = Math.PI / 2;
  m.position.y = y;
  trophy.add(m);
}
ring(0.2, 0.068, 0.016, goldDarkPlain);
ring(0.5, 0.058, 0.012, goldDarkPlain);
ring(0.085, 0.2, 0.01, goldDarkPlain);

// handles
const handleCurve = (sign: number) =>
  new THREE.CatmullRomCurve3(
    (
      [
        [0.34, 0.99],
        [0.5, 1.09],
        [0.64, 1.02],
        [0.68, 0.86],
        [0.58, 0.7],
        [0.4, 0.62],
        [0.2, 0.6],
        [0.12, 0.6],
      ] as [number, number][]
    ).map(([x, y]) => new THREE.Vector3(sign * x, y, 0)),
    false,
    'centripetal',
  );
for (const sign of [1, -1]) {
  trophy.add(shadowed(new THREE.Mesh(new THREE.TubeGeometry(handleCurve(sign), 96, 0.03, 16), gold), true, false));
}

// ---------- Lights ----------
scene.add(new THREE.HemisphereLight(0x3a2e28, 0x120c08, 0.35));

const spot = new THREE.SpotLight(0xffd9a2, 330, 0, 0.36, 0.85, 2);
spot.position.set(2.2, 6.6, 6.2);
spot.target.position.set(0, 1.5, 0);
spot.castShadow = true;
spot.shadow.mapSize.set(2048, 2048);
spot.shadow.radius = 7;
spot.shadow.bias = -0.0003;
spot.shadow.normalBias = 0.02;
spot.shadow.camera.near = 3;
spot.shadow.camera.far = 20;
scene.add(spot, spot.target);

const fill = new THREE.DirectionalLight(0x8aa4d6, 0.35);
fill.position.set(-6, 3, 4);
scene.add(fill);

const rim = new THREE.SpotLight(0xffe2b8, 220, 0, 0.5, 0.7, 2);
rim.position.set(-3.5, 5, -5.5);
rim.target.position.set(0, 1.8, 0);
scene.add(rim, rim.target);

// ---------- Animation ----------
window.__TASK_STATE__ = { materials: ['marble', 'gold', 'darkstone'], cameraAzimuthDeg: 0 };

const RADIUS = 7.4;
const CAM_H = 2.5;
const AMPLITUDE = 15;

function setCamera(timeSec: number): void {
  const az = AMPLITUDE * Math.sin(timeSec * 0.28);
  const a = THREE.MathUtils.degToRad(az);
  camera.position.set(target.x + RADIUS * Math.sin(a), CAM_H, target.z + RADIUS * Math.cos(a));
  camera.lookAt(target);
  window.__TASK_STATE__.cameraAzimuthDeg = az;
}

const t0 = performance.now();
let first = true;
function frame(): void {
  setCamera((performance.now() - t0) / 1000);
  renderer.render(scene, camera);
  if (first) {
    first = false;
    window.__EVAL_READY__ = true;
  }
  requestAnimationFrame(frame);
}
setCamera(0);
requestAnimationFrame(frame);
